def statvfs(path: str) -> MP_StatVfsResult:
    """
    Get the status of a filesystem.

    Returns a 10-tuple (see ``statvfs_result``) with the block size, fragment size,
    block counts, inode counts, mount flags, and maximum filename length.
    """
    ...


